        .conversations
        .list_sessions()
        .await
        .into_iter()
        .map(|(id, msg_count, title)| {
            json!({
                "id": id,
                "title": title,
                "date": chrono::Utc::now().to_rfc3339(),
                "messages": msg_count
            })
        })
        .collect();

