   424	/// Convert an `op_state_store::PluginSchema` into an `op_projection::PluginSchema`.
   425	pub fn convert_schema(schema: &RuntimePluginSchema) -> PluginSchema {
   426	    PluginSchema {
   427	        name: schema.name.clone(),
   428	        version: schema.version.clone(),
   429	        fields: schema
   430	            .fields
   431	            .iter()
   432	            .map(|(name, field)| convert_field(name, field))
   433	            .collect(),
   434	        category: Some(schema.category.clone()),
   435	        examples: schema.example.clone().map(|example| vec![example]),
   436	        secret_paths: Vec::new(),
