   440	
   441	fn convert_field(name: &str, field: &RuntimeFieldSchema) -> FieldSchema {
   442	    FieldSchema {
   443	        name: name.to_string(),
   444	        field_type: convert_field_type(&field.field_type),
   445	        required: field.required,
   446	        description: Some(field.description.clone()).filter(|description| !description.is_empty()),
   447	        constraints: field
   448	            .constraints
   449	            .iter()
   450	            .filter_map(convert_constraint)
   451	            .collect(),
   452	        example: field.example.clone(),
   453	        read_only: field.read_only,
   454	    }
   455	}
   456	
   457	fn convert_field_type(field_type: &RuntimeFieldType) -> FieldType {
   458	    match field_type {
   459	        RuntimeFieldType::String => FieldType::String,
   460	        RuntimeFieldType::Integer => FieldType::Integer,
   461	        RuntimeFieldType::Float => FieldType::Number,
   462	        RuntimeFieldType::Boolean => FieldType::Boolean,
   463	        RuntimeFieldType::Array(inner) => FieldType::Array(Box::new(convert_field_type(inner))),
   464	        RuntimeFieldType::Object(_) => FieldType::Object,
   465	        RuntimeFieldType::Enum(values) => FieldType::Enum(values.clone()),
   466	        RuntimeFieldType::Any => FieldType::Any,
   467	    }
   468	}
   469	
   470	fn convert_constraint(constraint: &RuntimeConstraint) -> Option<Constraint> {
   471	    match constraint {
   472	        RuntimeConstraint::Min { value } => Some(Constraint::MinValue(*value as i64)),
   473	        RuntimeConstraint::Max { value } => Some(Constraint::MaxValue(*value as i64)),
   474	        RuntimeConstraint::Pattern { regex } => Some(Constraint::Pattern(regex.clone())),
   475	        RuntimeConstraint::OneOf { values } => {
   476	            let values = values
   477	                .iter()
   478	                .filter_map(|value| value.as_str().map(ToString::to_string))
   479	                .collect::<Vec<_>>();
   480	
   481	            if values.is_empty() {
   482	                None
   483	            } else {
   484	                Some(Constraint::Enum(values))
   485	            }
   486	        }
   487	        RuntimeConstraint::RequiresField { .. } | RuntimeConstraint::Custom { .. } => None,
   488	    }
   489	}
