    56	/// Derives the D-Bus object path from a projection's entity_type and entity_id.
    57	///
    58	/// entity_type "system.memory"    → /org/opdbus/system/memory
    59	/// entity_type "system.process"   → /org/opdbus/system/process/<entity_id>
    60	/// entity_type "identity.sled"    → /org/opdbus/identity/sled
    61	/// entity_type "ovsdb_bridge"     → /org/opdbus/ovsdb/bridge/<entity_id>
    62	pub fn projection_path(entity_type: &str, entity_id: &str) -> String {
    63	    // Replace dots and underscores in type with slashes for the path prefix
    64	    let type_path = entity_type
    65	        .replace('.', "/")
    66	        .replace('_', "/")
    67	        .to_lowercase();
    68	
    69	    // For singleton objects (memory, cpu, filesystems, network) the entity_id
    70	    // is typically the same as the type — omit it to avoid redundancy.
    71	    let is_singleton = entity_id == entity_type
    72	        || entity_id.is_empty()
    73	        || entity_id == "memory"
    74	        || entity_id == "cpu"
    75	        || entity_id == "filesystems"
    76	        || entity_id == "network"
    77	        || entity_id == "sled";
    78	
    79	    if is_singleton {
    80	        format!("/org/opdbus/{}", type_path)
    81	    } else {
    82	        // Sanitize entity_id for use in a path segment
    83	        let safe_id: String = entity_id
    84	            .chars()
    85	            .map(|c| {
    86	                if c.is_ascii_alphanumeric() || c == '_' {
    87	                    c
    88	                } else {
    89	                    '_'
    90	                }
    91	            })
    92	            .collect();
    93	        format!("/org/opdbus/{}/{}", type_path, safe_id)
    94	    }
    95	}
