     1	//! D-Bus Service Wrapper for AgentTrait implementations
     2	//!
     3	//! Exposes agents via D-Bus with standard interface: org.dbusmcp.Agent
     4	//! This allows agents to be discovered by the ChatActor's tool_loader
     5	//! and registered as tools that the LLM can call.
     6	//!
     7	//! # Architecture Integration
     8	//!
     9	//! ```text
    10	//! ChatActor (brain)
    11	//!    └── ToolRegistry
    12	//!           └── AgentTool (wraps D-Bus calls)
    13	//!                  └── D-Bus Call to org.dbusmcp.Agent.{AgentType}
    14	//!                         └── DbusAgentService (this module)
    15	//!                                └── AgentTrait implementation
    16	//! ```
    17	//!
    18	//! # Example
    19	//!
    20	//! ```rust,ignore
    21	//! use op_agents::{create_agent, dbus_service};
    22	//! use op_core::BusType;
    23	//!
    24	//! let agent = create_agent("python-pro", "python-1".to_string()).unwrap();
    25	//! let connection = dbus_service::start_agent(agent, "python-1", BusType::Session).await?;
    26	//! // Agent is now discoverable via D-Bus introspection
    27	//! ```
