    90	#[interface(name = "org.dbusmcp.Agent")]
    91	impl DbusAgentService {
    92	    //
    93	    // === Core Execution Methods ===
    94	    //
    95	
    96	    /// Execute a task on the agent
    97	    ///
    98	    /// # Arguments
    99	    /// * `task_json` - JSON-encoded AgentTask:
   100	    ///   ```json
   101	    ///   {
   102	    ///     "type": "python-pro",
   103	    ///     "operation": "test",
   104	    ///     "path": "/home/user/project",
   105	    ///     "args": "--verbose",
   106	    ///     "config": {}
   107	    ///   }
   108	    ///   ```
   109	    ///
   110	    /// # Returns
   111	    /// JSON-encoded TaskResult
   112	    async fn execute(&self, task_json: String) -> Result<String, zbus::fdo::Error> {
   113	        debug!(
   114	            "[{}] Execute called: {}",
   115	            self.agent_id,
   116	            &task_json[..task_json.len().min(200)]
   117	        );
   118	
   119	        let mut task_json_mut = task_json.to_string();
   120	        let task: AgentTask = unsafe { simd_json::from_str(&mut task_json_mut) }.map_err(|e| {
   121	            error!("[{}] Invalid task JSON: {}", self.agent_id, e);
   122	            zbus::fdo::Error::InvalidArgs(format!("Invalid task JSON: {}", e))
   123	        })?;
   124	
   125	        let agent = self.agent.read().await;
   126	
   127	        // Validate operation is supported
   128	        if !agent.supports_operation(&task.operation) {
   129	            return Err(zbus::fdo::Error::InvalidArgs(format!(
   130	                "Unsupported operation '{}'. Supported: {:?}",
   131	                task.operation,
   132	                agent.operations()
   133	            )));
   134	        }
   135	
   136	        let result = agent.execute(task).await.map_err(|e| {
   137	            error!("[{}] Execution failed: {}", self.agent_id, e);
   138	            zbus::fdo::Error::Failed(format!("Execution failed: {}", e))
   139	        })?;
   140	
   141	        simd_json::to_string(&result).map_err(|e| {
   142	            error!("[{}] Serialization failed: {}", self.agent_id, e);
   143	            zbus::fdo::Error::Failed(format!("Serialization failed: {}", e))
   144	        })
   145	    }
   146	
   147	    /// Execute an operation directly (convenience method)
   148	    ///
   149	    /// Simpler than Execute - just pass operation name and path
   150	    async fn run_operation(
   151	        &self,
   152	        operation: String,
   153	        path: String,
   154	        args: String,
   155	    ) -> Result<String, zbus::fdo::Error> {
   156	        let task = AgentTask {
   157	            task_type: self.agent_type.clone(),
   158	            operation,
   159	            path: if path.is_empty() { None } else { Some(path) },
   160	            args: if args.is_empty() { None } else { Some(args) },
   161	            config: std::collections::HashMap::new(),
   162	        };
   163	
   164	        let task_json = simd_json::to_string(&task)
   165	            .map_err(|e| zbus::fdo::Error::Failed(format!("Failed to serialize task: {}", e)))?;
   166	
   167	        self.execute(task_json).await
   168	    }
