   142	impl AgentExecutor for TraitAgentExecutor {
   143	    async fn start_agent(&self, agent_id: &str, _dbus_service: Option<&str>) -> Result<()> {
   144	        let mut agents = self.agents.write().await;
   145	        
   146	        if let Some(entry) = agents.get_mut(agent_id) {
   147	            entry.started = true;
   148	            info!(agent = %agent_id, "✓ Agent started (trait-based)");
   149	            Ok(())
   150	        } else {
   151	            warn!(agent = %agent_id, "Agent not found in registry");
   152	            Err(anyhow::anyhow!("Agent not registered: {}", agent_id))
   153	        }
   154	    }
   155	    
   156	    async fn stop_agent(&self, agent_id: &str) -> Result<()> {
   157	        let mut agents = self.agents.write().await;
   158	        
   159	        if let Some(entry) = agents.get_mut(agent_id) {
   160	            entry.started = false;
   161	            info!(agent = %agent_id, "Agent stopped");
   162	        }
   163	        
   164	        Ok(())
   165	    }
   166	    
   167	    async fn execute(&self, agent_id: &str, operation: &str, args: Value) -> Result<Value> {
   168	        debug!(agent = %agent_id, operation = %operation, "Executing agent");
   169	        
   170	        let agents = self.agents.read().await;
   171	        
   172	        let entry = agents.get(agent_id)
   173	            .ok_or_else(|| anyhow::anyhow!("Agent not found: {}", agent_id))?;
   174	        
   175	        // Build task
   176	        let task = AgentTask {
   177	            task_type: entry.agent.agent_type().to_string(),
   178	            operation: operation.to_string(),
   179	            path: args.get("path").and_then(|p| p.as_str()).map(String::from),
   180	            args: Some(simd_json::to_string(&args).unwrap_or_else(|_| "{}".to_string())),
   181	            config: args.as_object()
   182	                .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
   183	                .unwrap_or_default(),
   184	        };
   185	        
   186	        // Execute
   187	        match entry.agent.execute(task).await {
   188	            Ok(result) => {
   189	                debug!(agent = %agent_id, success = %result.success, "Agent execution complete");
   190	                
   191	                Ok(json!({
   192	                    "success": result.success,
   193	                    "operation": result.operation,
   194	                    "output": result.data,
   195	                    "agent": agent_id
   196	                }))
   197	            }
   198	            Err(e) => {
   199	                error!(agent = %agent_id, error = %e, "Agent execution failed");
   200	                Err(anyhow::anyhow!("Agent {} failed: {}", agent_id, e))
   201	            }
   202	        }
   203	    }
   204	    
   205	    async fn is_running(&self, agent_id: &str) -> bool {
   206	        self.agents.read().await
   207	            .get(agent_id)
   208	            .map(|e| e.started)
   209	            .unwrap_or(false)
   210	    }
   211	}
