    84	fn build_context_query(tool_name: &str, arguments: &Value, current_file: Option<&str>) -> String {
    85	    let mut parts: Vec<String> = Vec::new();
    86	
    87	    // Tool category gives context
    88	    if tool_name.contains("file") || tool_name.contains("write") {
    89	        parts.push("file operations".to_string());
    90	    } else if tool_name.contains("network") || tool_name.contains("ovs") {
    91	        parts.push("network configuration".to_string());
    92	    } else if tool_name.contains("service") || tool_name.contains("systemd") {
    93	        parts.push("service management".to_string());
    94	    } else if tool_name.contains("shell") || tool_name.contains("exec") {
    95	        parts.push("shell scripting".to_string());
    96	    }
    97	
    98	    // Current file path
    99	    if let Some(f) = current_file {
   100	        parts.push(f.to_string());
   101	    }
   102	
   103	    // Arguments hint at intent
   104	    if let Some(obj) = arguments.as_object() {
   105	        for (k, v) in obj {
   106	            parts.push(format!("{}: {}", k, v));
   107	        }
   108	    }
   109	
   110	    parts.join(" ")
   111	}
