   122	async fn search_code(query: &str, _repo: Option<&str>, limit: usize) -> Result<Vec<CodeSnippet>> {
   123	    // Call the existing code search via HTTP to Qdrant
   124	    let client = reqwest::Client::new();
   125	    let qdrant_url =
   126	        std::env::var("QDRANT_URL").unwrap_or_else(|_| "http://127.0.0.1:6333".to_string());
   127	
   128	    // Embed query (simplified - would use HF API in production)
   129	    let embedding = embed_text(query).await?;
   130	
   131	    // Search Qdrant
   132	    let url = format!("{}/collections/code_chunks/points/query", qdrant_url);
   133	    let response = client
   134	        .post(&url)
   135	        .json(&serde_json::json!({
   136	            "query": embedding,
   137	            "limit": limit,
   138	            "with_payload": true
   139	        }))
   140	        .send()
   141	        .await
   142	        .ok();
   143	
   144	    let mut snippets = Vec::new();
   145	    if let Some(r) = response {
   146	        if let Ok(json) = r.json::<serde_json::Value>().await {
   147	            if let Some(results) = json.pointer("/result/points").and_then(|p| p.as_array()) {
   148	                for point in results {
   149	                    if let Some(payload) = point.pointer("/payload") {
   150	                        snippets.push(CodeSnippet {
