        )
        // LLM endpoints
        .route("/llm/status", get(handlers::llm::llm_status_handler))
        .route("/llm/providers", get(handlers::llm::list_providers_handler))
        .route("/llm/models", get(llm::get_models))
        .route(
            "/llm/models/:provider",
            get(handlers::llm::list_models_for_provider_handler),
        )
        .route(
            "/llm/provider",
