type ChatTab = "chat" | "system-prompt";
type LlmModelOption = { id: string; name?: string; available?: boolean };
type ProviderOption = {
  id: string;
  label: string;
  description: string;
  available?: boolean;
};

const PROVIDER_OPTIONS: ProviderOption[] = [
  { id: "codex", label: "Codex", description: "Codex / local factory route" },
  { id: "opencode", label: "Opencode", description: "Opencode local / CLI router" },
  { id: "kilocode", label: "KiloCode", description: "KiloCode provider route" },
  { id: "openrouter", label: "OpenRouter", description: "OpenRouter provider route" },
  { id: "openai", label: "OpenAI", description: "OpenAI API" },
  { id: "anthropic", label: "Anthropic", description: "Claude via Anthropic" },
  { id: "google", label: "Google", description: "Gemini / Google AI" },
  { id: "gemini", label: "Gemini", description: "Gemini API (legacy alias)" },
  { id: "gemini-cli", label: "Gemini CLI", description: "Gemini CLI provider" },
  { id: "factory", label: "Factory", description: "Local proxy / current gateway" },
  { id: "mcp-proxy", label: "MCP Proxy", description: "Model via MCP proxy" },
  { id: "perplexity", label: "Perplexity", description: "Perplexity API" },
  { id: "huggingface", label: "Hugging Face", description: "HF endpoint" },
  { id: "antigravity", label: "Antigravity", description: "OAuth-backed route" },
];
const FALLBACK_PROVIDER = "factory";

function providerList(payload: unknown): string[] {
  const value = payload as { providers?: unknown[]; current?: unknown; provider?: unknown } | null;
  return Array.from(
    new Set(
      [
        value?.current,
        value?.provider,
        ...(Array.isArray(value?.providers) ? value.providers : []),
      ]
        .filter(Boolean)
        .map(String),
    ),
  );
}

function modelList(payload: unknown): LlmModelOption[] {
  const value = payload as { models?: unknown[] } | null;
  const models = Array.isArray(value?.models) ? value.models : [];
  return models
    .map((item) => {
      const model = item as { id?: unknown; name?: unknown; available?: unknown };
      const id = model.id ?? model.name;
      if (!id) return null;
      return {
        id: String(id),
        name: String(model.name ?? id),
        available: model.available !== false,
      };
    })
    .filter(Boolean) as LlmModelOption[];
}

function historyMessages(payload: unknown): LocalMessage[] {
  const value = payload as { messages?: unknown[] } | unknown[];
  const messages = Array.isArray(value)
    ? value
    : Array.isArray(value?.messages)
      ? value.messages
      : [];

  return messages.map((item, index) => {
    const msg = item as { id?: unknown; role?: unknown; content?: unknown; timestamp?: unknown };
    return {
      id: String(msg.id ?? `history-${index}`),
      role: String(msg.role ?? "assistant") as LocalMessage["role"],
      content: String(msg.content ?? ""),
      timestamp: msg.timestamp ? Date.parse(String(msg.timestamp)) || Date.now() : Date.now(),
    };
  });
}

function assistantMessage(payload: unknown): LocalMessage {
  const value = payload as {
    id?: unknown;
    role?: unknown;
    content?: unknown;
    message?: unknown;
    error?: unknown;
  };
  const body = value?.content ?? value?.message ?? value?.error ?? "(no response)";
  return {
    id: String(value?.id ?? `msg-${Date.now()}-resp`),
    role: String(value?.role ?? "assistant") as LocalMessage["role"],
    content: typeof body === "string" ? body : JSON.stringify(body, null, 2),
    timestamp: Date.now(),
  };
}

